package com.example.paymentservicefeb25.models; import jakarta.persistence.*; import lombok.Getter; import lombok.Setter; import java.time.Instant;
@Entity @Table(name="processed_payment_events",uniqueConstraints=@UniqueConstraint(name="uk_payment_event",columnNames="event_id")) @Getter @Setter public class ProcessedPaymentEvent { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="event_id",nullable=false) private String eventId; @Column(nullable=false) private Instant processedAt; }
